// Decrypter
//
// The static class that handles decryption of encrypted files.
// This version is simplified for use with raw JSON files.

function Decrypter() {
    throw new Error('This is a static class');
}

Decrypter.hasEncryptedImages = false;
Decrypter.hasEncryptedAudio = false;

Decrypter.decrypt = function(source) {
    // No decryption needed - return the source as-is
    return source;
};

Decrypter.extToEncryptExt = function(url) {
    // No encryption - return the URL unchanged
    return url;
};

Decrypter.decryptHTML5Audio = function(url, bgm, pos) {
    // For raw JSON files, just load the audio normally
    AudioManager._blobUrl = url;
    AudioManager._bgmBuffer = AudioManager.createBuffer('bgm', bgm.name);
    AudioManager.updateBgmParameters(bgm);
    if (!AudioManager._meBuffer) {
        AudioManager._bgmBuffer.play(true, pos || 0);
    }
};

Decrypter.checkImgIgnore = function(url) {
    // No image ignore check needed for raw files
    return false;
};



